import{_ as l,a0 as r,w as o,s as p,ao as d,I as i,x as n,a1 as t,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const M=JSON.parse('{"title":"Linux 上的 NVMe | LCTT x X-CMD","titleTemplate":false,"description":"Linux 上的 NVMe | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 上的 NVMe | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 上的 NVMe | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190529 NVMe on Linux","title":"Linux 上的 NVMe","tag":"201906","desc":""},"relativePath":"201906/20190529 NVMe on Linux.md","filePath":"[post].md"}'),u={name:"201906/20190529 NVMe on Linux.md"};function m(g,e,x,f,k,h){const s=r("Link");return o(),p("div",null,[e[21]||(e[21]=d(`<h1 id="linux-上的-nvme" tabindex="-1">Linux 上的 NVMe <a class="header-anchor" href="#linux-上的-nvme" aria-label="Permalink to “Linux 上的 NVMe”">​</a></h1><blockquote><p>如果你还没注意到，一些极速的固态磁盘技术已经可以用在 Linux 和其他操作系统上了。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/05/nvme-100797708-large.jpg" alt="Sandra Henry-Stocker"></p><p>NVMe 意即<ruby>非易失性内存主机控制器接口规范<rt>non-volatile memory express</rt></ruby>，它是一个主机控制器接口和存储协议，用于加速企业和客户端系统以及固态驱动器（SSD）之间的数据传输。它通过电脑的高速 PCIe 总线工作。每当我看到这些名词时，我的感受是“羡慕”。而羡慕的原因很重要。</p><p>使用 NVMe，数据传输的速度比旋转磁盘快很多。事实上，NVMe 驱动能够比 SATA SSD 快 7 倍。这比我们今天很多人用的固态硬盘快了 7 倍多。这意味着，如果你用一个 NVMe 驱动盘作为启动盘，你的系统能够启动的非常快。事实上，如今任何人买一个新的系统可能都不会考虑那些没有自带 NVMe 的，不管是服务器或者个人电脑。</p><h3 id="nvme-在-linux-下能工作吗" tabindex="-1">NVMe 在 Linux 下能工作吗？ <a class="header-anchor" href="#nvme-在-linux-下能工作吗" aria-label="Permalink to “NVMe 在 Linux 下能工作吗？”">​</a></h3><p>是的！NVMe 自 Linux 内核 3.3 版本就支持了。然而，要升级系统，通常同时需要一个 NVMe 控制器和一个 NVMe 磁盘。一些外置磁盘也行，但是要连接到系统上，需要的可不仅仅是通用的 USB 接口。</p><p>先使用下列命令检查内核版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -r</span></span>
<span class="line"><span>5.0.0-15-generic</span></span></code></pre></div><p>如果你的系统已经用了 NVMe，你将看到一个设备（例如，<code>/dev/nvme0</code>），但是只有在你安装了 NVMe 控制器的情况下才显示。如果你没有 NVMe 控制器，你可以用下列命令获取使用 NVMe 的相关信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ modinfo nvme | head -6</span></span>
<span class="line"><span>filename:       /lib/modules/5.0.0-15-generic/kernel/drivers/nvme/host/nvme.ko</span></span>
<span class="line"><span>version:        1.0</span></span>
<span class="line"><span>license:        GPL</span></span>
<span class="line"><span>author:         Matthew Wilcox &lt;willy@linux.intel.com&gt;</span></span>
<span class="line"><span>srcversion:     AA383008D5D5895C2E60523</span></span>
<span class="line"><span>alias:          pci:v0000106Bd00002003sv*sd*bc*sc*i*</span></span></code></pre></div><h3 id="了解更多" tabindex="-1">了解更多 <a class="header-anchor" href="#了解更多" aria-label="Permalink to “了解更多”">​</a></h3>`,12)),i("p",null,[e[1]||(e[1]=n("如果你想了解极速的 NVMe 存储的更多细节，可在 ",-1)),t(s,{href:"https://www.pcworld.com/article/2899351/everything-you-need-to-know-about-nvme.html"},{default:a(()=>[...e[0]||(e[0]=[n("PCWorld",-1)])]),_:1}),e[2]||(e[2]=n(" 获取。",-1))]),i("p",null,[e[4]||(e[4]=n("规范、白皮书和其他资源可在 ",-1)),t(s,{href:"https://nvmexpress.org/"},{default:a(()=>[...e[3]||(e[3]=[n("NVMexpress.org",-1)])]),_:1}),e[5]||(e[5]=n(" 获取。",-1))]),e[22]||(e[22]=i("hr",null,null,-1)),i("p",null,[e[7]||(e[7]=n("via: ",-1)),t(s,{href:"https://www.networkworld.com/article/3397006/nvme-on-linux.html"},{default:a(()=>[...e[6]||(e[6]=[n("https://www.networkworld.com/article/3397006/nvme-on-linux.html",-1)])]),_:1})]),i("p",null,[e[12]||(e[12]=n("作者：",-1)),t(s,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:a(()=>[...e[8]||(e[8]=[n("Sandra Henry-Stocker",-1)])]),_:1}),e[13]||(e[13]=n(" 选题：",-1)),t(s,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[9]||(e[9]=[n("lujun9972",-1)])]),_:1}),e[14]||(e[14]=n(" 译者：",-1)),t(s,{href:"https://github.com/warmfrog"},{default:a(()=>[...e[10]||(e[10]=[n("warmfrog",-1)])]),_:1}),e[15]||(e[15]=n(" 校对：",-1)),t(s,{href:"https://github.com/wxy"},{default:a(()=>[...e[11]||(e[11]=[n("wxy",-1)])]),_:1})]),i("p",null,[e[18]||(e[18]=n("本文由 ",-1)),t(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[16]||(e[16]=[n("LCTT",-1)])]),_:1}),e[19]||(e[19]=n(" 原创编译，",-1)),t(s,{href:"https://linux.cn/"},{default:a(()=>[...e[17]||(e[17]=[n("Linux中国",-1)])]),_:1}),e[20]||(e[20]=n(" 荣誉推出",-1))])])}const b=l(u,[["render",m]]);export{M as __pageData,b as default};
